root=Path(__file__).resolve().parents[1]
cards=json.loads((root/'assets/cards.json').read_text())
by={c['id']:c for c in cards}
source_url='https://www.easylaw.go.kr/CSP/CsmMain.laf?csmSeq='
urls={'workers':source_url+'2042','wages':source_url+'1694','dismissal':source_url+'514','injury':source_url+'570','benefits':source_url+'575','housing':source_url+'629','equality':source_url+'279','contract':source_url+'1347','parental':source_url+'1379','pension':'https://www.nps.or.kr/pnsinfo/ntpsklg/getOHAF0035M0.do','healthrates':'https://edi.nhis.or.kr/portal/images/popup/20251204_pop01longdesc.html'}
for c in cards:
 c['category']={'Visa':'ဗီဇာ','အဆောင်':'နေထိုင်မှု','ခံစားခွင့်':'လစာ','အခွန်':'လစာ','အကူအညီ':'အလုပ်'}.get(c['category'],c['category'])
 c['source_ids']=[{'အလုပ်':'workers','ဗီဇာ':'workers','လစာ':'wages','အာမခံ':'workers','နေထိုင်မှု':'housing'}.get(c['category'],'workers')]
 c['sections']=[]
def sections(ident,*rows):
 by[ident]['sections']=[dict(title=t,text=x) for t,x in rows]
def add(ident,title,category,summary,body,refs,tags,rows,steps,pending=False,url=None):
 c=dict(id=ident,title=title,category=category,summary=summary,body=body,source='တရားဝင်အဖွဲ့အစည်း၏ လက်စွဲ / အောက်ပါ မူရင်းရင်းမြစ်',url=url or urls[refs[0]],checked='2026-10-09',source_ids=refs,tags=tags,sections=[dict(title=t,text=x) for t,x in rows],steps=steps,pending=pending)
 by[ident]=c

for ident in ['dismissal20','noticepay','writtennotice','unfairdismissal']:
 by[ident]['source_ids']=['dismissal','workers']
sections('dismissal20',('သီးခြားစစ်ရမည့် အချက် ၃ ခု','၁။ အလုပ်ထုတ်ရသည့် တရားဝင်အကြောင်းရင်းရှိမရှိ။\n၂။ လုပ်ငန်းအကျုံးဝင်ပါက အကြောင်းရင်းနှင့် ရက်ကို စာဖြင့်ပေးမပေး။\n၃။ ရက် ၃၀ ကြိုအသိပေးမှု / အစားထိုးငွေနှင့် ခြွင်းချက်။\nဤအချက်များသည် တစ်ခုနှင့်တစ်ခု မတူပါ။ စမ်းသပ်ကာလဟု စာချုပ်မှာရေးထားရုံဖြင့် အကာအကွယ်အားလုံး ပျောက်မသွားပါ။'),('ဥပမာနှင့် မေးရန်','လုပ်သက် ရက်၂၀ဆို notice-pay ခြွင်းချက်ဖြစ်နိုင်သော်လည်း အလုပ်ရုံ၌ ပုံမှန်လုပ်သား ၅ ဦးနှင့်အထက်ရှိလျှင် တရားမျှတသောအကြောင်းရင်းနှင့် စာဖြင့်အသိပေးမှုကို ဆက်စစ်ပါ။ အလုပ်သမားရုံးတွင် 상시근로자 수와 해고사유를 확인하고 싶습니다 ဟု မေးနိုင်သည်။'))
sections('noticepay',('통상임금 ကို နားလည်ရန်','통상임금 သည် အမြဲတမ်း အနည်းဆုံးလုပ်ခနှင့် တူသောပမာဏမဟုတ်ပါ။ သဘောတူလုပ်ချိန်အတွက် ပုံမှန်နှင့် တစ်သမတ်တည်းပေးရန် သတ်မှတ်ထားသော အခကြေးငွေပစ္စည်းများကို စစ်ရသည်။ လစာစာရွက်တွင် 기본급၊ ပုံမှန်ထောက်ပံ့ကြေးနှင့် အလုပ်ချိန်အခြေခံတို့ကို စုပါ။'),('တောင်းဆိုမှုများကို ခွဲထားရန်','Notice-pay တောင်းဆိုမှု၊ မပေးရသေးသောလုပ်ခနှင့် မတရားအလုပ်ထုတ်မှု ဖြေရှင်းခွင့်တို့ကို သီးခြားတင်ပြပါ။ ငွေပေးပြီးကြောင်းစာကို မနားလည်ဘဲ အားလုံးပြေလည်ပြီးဟု လက်မှတ်မထိုးပါနှင့်။'))
sections('writtennotice',('အထောက်အထား ထိန်းသိမ်းရန်','ထုတ်မည့်ရက်၊ အကြောင်းရင်း၊ ပေးသူနှင့် လက်ခံရက်တို့ပါဝင်သည့် မူရင်းစာကို သိမ်းပါ။ မက်ဆေ့ချ်ဆို စကားဝိုင်းအပြည့်၊ ပေးပို့ရက်နှင့် sender ကို မြင်ရအောင်ထားပါ။ Screenshot တစ်ပုံထဲမှ စာဖြင့်အသိပေးမှု ပြည့်မပြည့်ကို အလိုအလျောက်မဆုံးဖြတ်ပါ။'),('မေးရန် ကိုရီးယားစာ','해고 사유와 해고 날짜가 적힌 서면을 주세요.\nအလုပ်ထုတ်အကြောင်းရင်းနှင့် အလုပ်ထုတ်ရက်ပါသော စာကို ပေးပါ။\nစာပေးရန် တောင်းခြင်းသည် အလုပ်ထုတ်မှုကို လက်ခံကြောင်း အဓိပ္ပာယ်မဟုတ်ပါ။'))
sections('unfairdismissal',('ရုံးလမ်းကြောင်း မရောရန်','노동위원회 သည် သက်ဆိုင်သော မတရားအလုပ်ထုတ်မှုကို စစ်ဆေးသောလမ်းကြောင်းဖြစ်သည်။ 고용노동부 노동청 သည် လစာမပေးမှု စသည့် အလုပ်သမားဥပဒေချိုးဖောက်မှုကို တိုင်ကြားရာဖြစ်သည်။ 고용센터 သည် E-9 အလုပ်ပြောင်းမှုကို ဆောင်ရွက်ရာဖြစ်သည်။'),('Deadline အထောက်အထား','ပြောခဲ့ရက်၊ နောက်ဆုံးအလုပ်ဆင်းရက်၊ စာမှာဖော်ပြသောထုတ်ရက်နှင့် လျှောက်လွှာတင်ရက်ကို ခွဲမှတ်ပါ။ အကြံပေးရုံး appointment ယူခြင်း၊ အလုပ်ရှင်နှင့်ညှိနှိုင်းခြင်းသည် deadline ကို အလိုအလျောက်ရပ်မထားပါ။'))
sections('resignation',('မထိုးမီဖတ်ရန်','사직서 သည် ကိုယ်တိုင်အလုပ်ထွက်စာ၊ 권고사직 သည် အလုပ်ရှင်၏အကြံပြုမှုဖြင့် ထွက်ခြင်း၊ 해고 သည် အလုပ်ထုတ်ခြင်းဖြစ်သည်။ အထက်ပါအမျိုးအစားများသည် အလုပ်ပြောင်းနှင့် ခံစားခွင့် အထောက်အထားအပေါ် သက်ရောက်နိုင်သည်။ မိမိအမှန်တကယ်အခြေအနေကို မမှန်သောအကြောင်းရင်းနှင့် မရေးပါနှင့်။'),('ထွက်ချိန် စစ်စာရင်း','နောက်ဆုံးလုပ်ခ၊ မသုံးသောခွင့်နှင့်ပတ်သက်သောငွေ၊ 퇴직금 အကျုံးဝင်မှု၊ အဆောင်မှပြောင်းရက်၊ အလုပ်ပြောင်း receipt နှင့် နေထိုင်ခွင့်ကုန်ဆုံးရက်ကို ခွဲစစ်ပါ။ အလုပ်အဆုံးသတ်သွားတာသည် ဗီဇာအချိန်ကာလကို အလိုအလျောက်အသစ်မစပါ။'))
for ident in ['change1month','search3months']:
 sections(ident,('고용센터 နှင့် 출입국','အလုပ်ပြောင်းလျှောက်ခြင်း၊ အလုပ်သစ်ရှာခြင်းနှင့် immigration ၏ 근무처 변경허가 သည် အဆင့်မတူပါ။ 고용센터 တွင် လျှောက်လွှာလက်ခံရက်နှင့် အလုပ်ရှာ deadline ကို သိမ်းပါ။ အလုပ်သစ်အတွက် immigration ဆောင်ရွက်ချက် ပြည့်မပြည့် သီးခြားစစ်ပါ။'),('ကိုယ့်ဖိုင်တွင် သိမ်းရမည့်စာ','စာချုပ်အဆုံးသတ်အထောက်အထား၊ အလုပ်ပြောင်းလျှောက်လွှာလက်ခံစာ၊ နိုင်ငံကူးလက်မှတ်၊ နေထိုင်ခွင့်ကတ်၊ အလုပ်သစ်စာချုပ်နှင့် ရုံး၏အတည်ပြုချက်တို့ကို သိမ်းပါ။ ခြွင်းချက်ကြောင့်ကာလရပ်နားလိုပါက ဆေးမှတ်တမ်းစသည့် တရားဝင်အထောက်အထားနှင့် ရုံးကို မေးပါ။'))
for ident in ['studentchange','e7route']:
 sections(ident,('မေးခွန်းကို တိကျအောင် ပြင်ရန်','လက်ရှိ visa အမျိုးအစားနှင့် subtype၊ နေထိုင်ခွင့်ကုန်ဆုံးရက်၊ အလုပ်ပြောင်းဆောင်ရွက်ဆဲရှိမရှိ၊ လိုချင်သော visa subtype နှင့် လျှောက်မည့်နေရာကို တိကျစွာဖော်ပြပါ။ အွန်လိုင်းမှ တစ်ဦး၏အောင်မြင်မှုသည် လူတိုင်းအတွက် ခွင့်ပြုချက်မဟုတ်ပါ။'),('အတည်ပြုသိမ်းရန်','သက်ဆိုင်ရာနှစ်၏ တရားဝင်ကြေညာချက်၊ လျှောက်ရမည့်စာရင်းနှင့် မိမိရုံး၏ညွှန်ကြားချက်ကို သိမ်းပါ။ 1345 အကြံပေးမှုနှင့် immigration အပြီးသတ်ခွင့်ပြုမှုကို ခွဲထားပါ။ ဝင်ခွင့်စာ၊ ချိန်းဆိုစာ သို့မဟုတ် ရွေးချယ်စာရရှိရုံဖြင့် အလုပ်လုပ်ခွင့် မပေါ်ပါ။'))
sections('minimum2026',('တစ်လလစာနှင့် ခွဲစစ်ရန်','တစ်နာရီ ၁၀,၃၂၀ ဝမ်သည် ၂၀၂၆ အနည်းဆုံးလုပ်ခဖြစ်သည်။ တစ်လလစာကို တိုက်ရိုက်နှိုင်းရန် paid hours အခြေခံ၊ အကျုံးဝင်သောလစာပစ္စည်းနှင့် ခြွင်းချက်ကို စစ်ရသည်။ လက်ခံရ net pay နည်းတာတစ်ခုတည်းမှ အနည်းဆုံးလုပ်ခချိုးဖောက်သည်ဟု မဆုံးဖြတ်ပါ။'),('အထောက်အထား','စာချုပ်ပါ 시급 / 월급၊ အမှန်တကယ်လုပ်ချိန်၊ ပေးချိန်နှင့် ဖြတ်တောက်ငွေတို့ကို စုပါ။ အဆောင်ခနှင့်အာမခံဖြတ်တောက်မှုကို အခြေခံလုပ်ခနှုန်းထဲ မရောပါနှင့်။'))
for ident in ['overtime','nightpay','holidaypay']:
 sections(ident,('နာရီနှင့် ငွေကို ထပ်မတွက်ရန်','အခြေခံလုပ်ခ၊ အချိန်ပိုထပ်ဆောင်းငွေ၊ ညပိုင်းထပ်ဆောင်းငွေနှင့် ပိတ်ရက်ထပ်ဆောင်းငွေကို သီးခြားခွဲပါ။ လစဉ်အခြေခံလစာတွင် ပါပြီးသား paid hours ကို ထပ်မထည့်ရန်လိုသည်။ အပိုကြေး၏ အခြေခံဖြစ်သော 통상임금 ကို စစ်ပါ။'),('အကျုံးဝင်မှုကို စစ်ရန်','ပုံမှန်လုပ်သားဦးရေ၊ လုပ်ငန်းကဏ္ဍ၊ စာချုပ်နှင့် သဘောတူအလုပ်ချိန်စနစ်တို့အရ စည်းမျဉ်းအကျုံးဝင်မှုကွာနိုင်သည်။ လယ်ယာ၊ မွေးမြူရေးနှင့် ငါးလုပ်ငန်းတွင် 근로기준법 제63조 ခြွင်းချက်ကို သီးခြားစစ်ရသည်။ ညကြေးကို အခြားခြွင်းချက်များနှင့် အလိုအလျောက်ပယ်မချပါနှင့်။'))
sections('payslip',('အသုံးများသော စာလုံးများ','기본급 — အခြေခံလစာ\n연장근로수당 — အချိန်ပိုကြေး\n야간근로수당 — ညကြေး\n휴일근로수당 — ပိတ်ရက်အလုပ်ကြေး\n공제 — ဖြတ်တောက်ငွေ\n실수령액 — အမှန်လက်ခံရငွေ\n건강보험 / 고용보험 / 국민연금 — အာမခံတစ်မျိုးစီ\n항목၊ 산정방법 နှင့် အမှန်ဘဏ်ဝင်ငွေကို ယှဉ်ပါ။'),('လစဉ်စစ်ပုံ','လုပ်ချိန်ကို နေ့အလိုက်ရေးထားပြီး စာရွက်တစ်ကြောင်းချင်းနှင့် ယှဉ်ပါ။ မကိုက်သောအချက်ကို လစဉ်တစ်ချက်ချင်း မေးပါ။ ပြန်တွက်ရလဒ်နှင့် employer ၏ရှင်းလင်းချက်ကို အတူသိမ်းပါ။'))
sections('dorm',('နေရာနှင့် စရိတ်ခွဲရန်','숙소 သည် နေရပ်၊ 기숙사 သည် အဆောင်၊ 숙식비 သည် နေစားစရိတ်ဖြစ်သည်။ အခန်းတစ်ခန်းနေသူဦးရေ၊ မီးရေခ၊ စားစရိတ်၊ လစာမှဖြတ်တောက်အခြေခံစာနှင့် မိမိအမှန်တကယ်လက်ခံရသောဝန်ဆောင်မှုကို ခွဲရေးပါ။'),('အန္တရာယ် သို့မဟုတ် မသင့်လျော်မှု','ထွက်ပေါက်ပိတ်ခြင်း၊ လျှပ်စစ်နှင့်မီးဘေးအန္တရာယ်၊ လုံခြုံရေးနှင့် ကိုယ်ပိုင်နေရာပြဿနာကို ရက်စွဲပါ ဓာတ်ပုံနှင့် မှတ်ပါ။ ချက်ချင်းအန္တရာယ်ရှိလျှင် လုံခြုံရာသို့ရွှေ့ပြီး 119 ဆက်ပါ။ E-9 အလုပ်ပြောင်းခွင့်အတွက် official recognition လိုမလို 고용센터 တွင်စစ်ပါ။'))
